T='src/content/posts/tech/2026-10-13-mit-67960-'
def ed(f,pairs):
    t=open(T+f).read()
    for a,b in pairs:
        assert t.count(a)==1,(f,a[:50],t.count(a)); t=t.replace(a,b)
    open(T+f,'w').write(t)
